To solve this problem, you can use dynamic programming to find the minimum difference between the values of the toys Alice and Bob received. Here's a C program that implements this approach:

```c
#include <stdio.h>
#include <string.h>

#define MAX_N 100000

int main() {
    int T;
    scanf("%d", &T);

    while (T--) {
        int N;
        char S[MAX_N + 1];
        scanf("%d %s", &N, S);

        // Initialize dp array with maximum value
        int dp[N + 1][2];
        memset(dp, N, sizeof(dp));

        // Base case: if there is only one toy, the difference is zero
        dp[0][0] = 0;
        dp[0][1] = 0;

        // Fill the dp array
        for (int i = 1; i <= N; i++) {
            if (S[i - 1] == '1') {
                dp[i][0] = dp[i - 1][0];
                dp[i][1] = dp[i - 1][1] + i;
            } else {
                dp[i][0] = dp[i - 1][0] + i;
                dp[i][1] = dp[i - 1][1];
            }
        }

        // Find the minimum difference
        int min_diff = N;
        for (int i = 0; i <= N; i++) {
            min_diff = fmin(min_diff, dp[i][0] - dp[i][1]);
        }

        // Check if the minimum difference is less than or equal to the maximum value
        printf((min_diff <= N) ? "YES\n" : "NO\n");
    }

    return 0;
}
```

