        }

        // XOR the byte array twice
        byte[] xorResult1 = new byte[piBytes.Length];
        byte[] xorResult2 = new byte[piBytes.Length];

        for (int i = 0; i < piBytes.Length; i++)
        {
            xorResult1[i] = piBytes[i] ^ 0x3F; // First XOR with 0x3F
            xorResult2[i] = xorResult1[i] ^ 0x3F; // Second XOR with 0x3F
        }

        // Convert the final XOR result back to a string
        string xorResultString = new string(xorResult2);

        // Print the final result
        Console.WriteLine("The final result after XORing π twice is: " + xorResultString);
    }
}
