```javascript
function fibonacciMod(n, p) {
    if (n <= 0) return 0;
    if (n === 1) return 1;

    let fib = [0, 1];
    for (let i = 2; i <= n; i++) {
        fib[i % 2] = (fib[(i - 1) % 2] + fib[(i - 2) % 2]) % p;
    }

    return fib[n % 2];
}

