contract ERC1155Creds {
    struct Token {
        string name;
        uint256 totalSupply;
        mapping(address => uint256) balances;
    }

    mapping(uint256 => Token) public tokens;

    event Transfer(address indexed from, address indexed to, uint256 id, uint256 amount);

    function mint(address _to, uint256 _id, uint256 _amount) public {
        require(_to != address(0), "ERC1155: mint to the zero address");
        require(tokens[_id].totalSupply + _amount <= 1000, "ERC1155: mint exceeds maximum supply");

        tokens[_id].balances[_to] += _amount;
        tokens[_id].totalSupply += _amount;

        emit Transfer(address(0), _to, _id, _amount);
    }

    function burn(address _from, uint256 _id, uint256 _amount) public {
        require(_from != address(0), "ERC1155: burn from the zero address");
        require(tokens[_id].balances[_from] >= _amount, "ERC1155: burn amount exceeds balance");

        tokens[_id].balances[_from] -= _amount;
        tokens[_id].totalSupply -= _amount;

        emit Transfer(_from, address(0), _id, _amount);
    }
}
