To generate a prime number stream in Rust, you can use the Sieve of Eratosthenes algorithm. Here's an example implementation:

```rust
use std::collections::HashSet;

fn sieve_of_eratosthenes(limit: u32) -> Vec<u32> {
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    for i in 2..=limit {
        if is_prime[i] {
            for j in (i * i)..=limit {
                is_prime[j] = false;
            }
        }
    }

    is_prime.into_iter().enumerate()
        .filter_map(|(i, p)| if p { Some(i as u32) } else { None })
        .collect()
}

fn main() {
    let limit = 100;
    let primes = sieve_of_eratosthenes(limit);
    println!("Prime numbers up to {}:", limit);
    for prime in primes {
        println!("{}", prime);
    }
}
```

