class RNN {
  private weights: number[][];

  constructor(inputSize: number, hiddenSize: number) {
    this.weights = new Array(hiddenSize).fill(0).map(() => new Array(inputSize + 1).fill(0));
  }

  public forward(inputs: number[]): number[] {
    const output = new Array(this.weights.length);
    let prevHiddenState = 0;

    for (let i = 0; i < inputs.length; i++) {
      const input = inputs[i];
      const inputPlusBias = [input, 1];

      for (let j = 0; j < this.weights.length; j++) {
        const weight = this.weights[j][i];
        prevHiddenState += weight * inputPlusBias[j];
      }

      output[j] = Math.tanh(prevHiddenState);
    }

    return output;
  }
}
