```javascript
import { defineStore } from 'pinia';
import { ref } from 'vue';
import { useQuery } from '@tanstack/vue-query';

export const useSessionStore = defineStore('session', () => {
  const sessionData = ref(null);

  const getSession = useQuery({
    queryKey: ['getSession'],
    queryFn: async () => {
      const response = await fetch('/get_session');
      if (!response.ok) {
        throw new Error('Failed to fetch session data');
      }
      return response.json();
    },
    select: (data) => {
      // Select specific keys in the response
      return {
        id: data.id,
        name: data.name,
        email: data.email,
      };
    },
  });

  return {
    sessionData,
    getSession,
  };
});
```

4. Use the global pinia store in your component:
```javascript
<template>
